#!/usr/bin/env node
/**
 * check.mjs — Cross-platform package check for AgentAudit
 * Works on Windows, macOS, and Linux. No bash/jq required.
 *
 * Usage:
 *   node scripts/check.mjs <package-name>
 *   node scripts/check.mjs --hash <sha256|git-sha|purl|swhid>
 *
 * Requires: Node.js 18+ (for built-in fetch)
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const API_URL = 'https://www.agentaudit.dev';
const MAX_RETRIES = 3;

// ── Helpers ──────────────────────────────────────────────

function loadApiKey() {
  if (process.env.AGENTAUDIT_API_KEY) return process.env.AGENTAUDIT_API_KEY;

  const skillCred = process.env.AGENTAUDIT_HOME
    ? path.join(process.env.AGENTAUDIT_HOME, 'config', 'credentials.json')
    : path.join(__dirname, '..', 'config', 'credentials.json');

  if (fs.existsSync(skillCred)) {
    try {
      const data = JSON.parse(fs.readFileSync(skillCred, 'utf8'));
      if (data.api_key) return data.api_key;
    } catch {}
  }

  const home = process.env.HOME || process.env.USERPROFILE || '';
  const xdg = process.env.XDG_CONFIG_HOME || path.join(home, '.config');
  const userCred = path.join(xdg, 'agentaudit', 'credentials.json');

  if (fs.existsSync(userCred)) {
    try {
      const data = JSON.parse(fs.readFileSync(userCred, 'utf8'));
      if (data.api_key) return data.api_key;
    } catch {}
  }

  return '';
}

async function fetchRetry(url, options = {}, retries = MAX_RETRIES) {
  let lastError;
  let delay = 2000;
  for (let i = 0; i < retries; i++) {
    try {
      return await fetch(url, { ...options, signal: AbortSignal.timeout(10_000) });
    } catch (err) {
      lastError = err;
      if (i < retries - 1) {
        await new Promise(r => setTimeout(r, delay));
        delay *= 2;
      }
    }
  }
  throw lastError;
}

// ── Args ─────────────────────────────────────────────────

const args = process.argv.slice(2);
if (args.length < 1) {
  console.error('Usage: node scripts/check.mjs <package-name>');
  console.error('       node scripts/check.mjs --hash <hash-value>');
  process.exit(1);
}

const apiKey = loadApiKey();
const headers = {};
if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;

// ── Hash lookup mode ─────────────────────────────────────

if (args[0] === '--hash' || args[0] === '-H') {
  if (args.length < 2) {
    console.error('Usage: node scripts/check.mjs --hash <hash-value>');
    process.exit(1);
  }
  const hash = args[1];
  const encoded = encodeURIComponent(hash);

  console.log(`Looking up hash '${hash}' against ${API_URL}...`);
  console.log('');

  let data;
  try {
    const res = await fetchRetry(`${API_URL}/api/lookup?hash=${encoded}`, { headers });
    data = await res.json();
  } catch {
    console.log('Registry unreachable. Cannot look up hash.');
    process.exit(2);
  }

  const detectedType = data.detected_type || 'unknown';
  const total = data.total_matches || 0;
  const reports = data.reports || [];
  const findings = data.findings || [];

  console.log(`   Type: ${detectedType}`);
  console.log(`   Matches: ${total} (${reports.length} reports, ${findings.length} findings)`);
  console.log('');

  if (reports.length > 0) {
    console.log('   Reports:');
    for (const r of reports) {
      console.log(`   - ${r.skill_slug} — score ${r.risk_score}, matched ${r.matched_field}`);
    }
    console.log('');
  }

  if (findings.length > 0) {
    console.log('   Findings:');
    for (const f of findings) {
      console.log(`   - [${(f.severity || '').toUpperCase()}] ${f.asf_id}: ${f.title} (matched ${f.matched_field})`);
    }
    console.log('');
  }

  if (total === 0) {
    console.log('No audit data matches this hash.');
  }
  process.exit(0);
}

// ── Package name mode ────────────────────────────────────

const pkg = args[0];
const encoded = encodeURIComponent(pkg);

console.log(`Checking '${pkg}' against ${API_URL}...`);
console.log('');

// Fetch trust score from /api/check
let checkData;
try {
  const res = await fetchRetry(`${API_URL}/api/check?package=${encoded}`, { headers });
  checkData = await res.json();
} catch {
  console.log('Registry unreachable. Cannot verify package.');
  console.log('Try again later or run a local LLM audit on the source.');
  process.exit(2);
}

if (!checkData.exists) {
  console.log(`No audit data found for '${pkg}'.`);
  console.log('This package has not been scanned yet.');
  console.log('Consider submitting an audit: node scripts/upload.mjs <report.json>');
  process.exit(0);
}

const score = checkData.trust_score ?? 0;
const crit = checkData.critical ?? 0;
const high = checkData.high ?? 0;
const med = checkData.medium ?? 0;
const low = checkData.low ?? 0;

// Fetch findings for by_design count
let byDesign = 0;
try {
  const fRes = await fetchRetry(`${API_URL}/api/findings?package=${encoded}`, { headers });
  const fData = await fRes.json();
  byDesign = (fData.findings || []).filter(f => f.by_design === true || f.by_design === 'true').length;
} catch {}

// Decision
let icon, verdict;
if (score >= 70) {
  icon = 'PASS'; verdict = 'Safe to install';
} else if (score >= 40) {
  icon = 'CAUTION'; verdict = 'Review findings before installing';
} else {
  icon = 'UNSAFE'; verdict = 'Do not install without careful review';
}

console.log(`${icon} ${pkg} — Score: ${score}/100`);
console.log(`   ${verdict}`);
console.log('');
console.log(`   Findings: ${crit} critical | ${high} high | ${med} medium | ${low} low | ${byDesign} by-design`);
console.log('');

// Show top findings if score is low
if (score < 70) {
  console.log('   Top findings:');
  try {
    const fRes = await fetchRetry(`${API_URL}/api/findings?package=${encoded}`, { headers });
    const fData = await fRes.json();
    const top = (fData.findings || [])
      .filter(f => f.by_design !== true && f.by_design !== 'true')
      .slice(0, 5);
    for (const f of top) {
      console.log(`   - [${(f.severity || '').toUpperCase()}] ${f.title} (${f.file || 'unknown'})`);
    }
  } catch {}
}

#!/usr/bin/env node
/**
 * gate.mjs — Cross-platform security gate for AgentAudit
 * Works on Windows, macOS, and Linux. No bash/jq required.
 *
 * Usage:
 *   node scripts/gate.mjs <manager> <package>
 *   node scripts/gate.mjs npm express
 *   node scripts/gate.mjs pip requests
 *
 * Exit codes: 0=PASS, 1=BLOCK, 2=WARN, 3=UNKNOWN
 *
 * Requires: Node.js 18+ (for built-in fetch)
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const API_URL = 'https://www.agentaudit.dev';
const MAX_RETRIES = 3;

// ── Helpers ──────────────────────────────────────────────

function loadApiKey() {
  if (process.env.AGENTAUDIT_API_KEY) return process.env.AGENTAUDIT_API_KEY;

  const skillCred = process.env.AGENTAUDIT_HOME
    ? path.join(process.env.AGENTAUDIT_HOME, 'config', 'credentials.json')
    : path.join(__dirname, '..', 'config', 'credentials.json');

  if (fs.existsSync(skillCred)) {
    try {
      const data = JSON.parse(fs.readFileSync(skillCred, 'utf8'));
      if (data.api_key) return data.api_key;
    } catch {}
  }

  const home = process.env.HOME || process.env.USERPROFILE || '';
  const xdg = process.env.XDG_CONFIG_HOME || path.join(home, '.config');
  const userCred = path.join(xdg, 'agentaudit', 'credentials.json');

  if (fs.existsSync(userCred)) {
    try {
      const data = JSON.parse(fs.readFileSync(userCred, 'utf8'));
      if (data.api_key) return data.api_key;
    } catch {}
  }

  return '';
}

async function fetchRetry(url, options = {}, retries = MAX_RETRIES) {
  let lastError;
  let delay = 2000;
  for (let i = 0; i < retries; i++) {
    try {
      return await fetch(url, { ...options, signal: AbortSignal.timeout(10_000) });
    } catch (err) {
      lastError = err;
      if (i < retries - 1) {
        await new Promise(r => setTimeout(r, delay));
        delay *= 2;
      }
    }
  }
  throw lastError;
}

function gateJson(gate, pkg, score, summary) {
  return JSON.stringify({ gate, package: pkg, score, ...summary });
}

// ── Args ─────────────────────────────────────────────────

const manager = process.argv[2];
const pkg = process.argv[3];

if (!manager || !pkg) {
  console.error('Usage: node scripts/gate.mjs <manager> <package>');
  console.error('       node scripts/gate.mjs npm express');
  process.exit(1);
}

const apiKey = loadApiKey();
const encoded = encodeURIComponent(pkg);

// ── Check API ────────────────────────────────────────────

let checkData;
try {
  const headers = {};
  if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;
  const res = await fetchRetry(`${API_URL}/api/check?package=${encoded}`, { headers });
  checkData = await res.json();
} catch (err) {
  console.error(`Registry unreachable: ${err.message}`);
  console.log(gateJson('WARN', pkg, null, { reason: 'registry_unreachable' }));
  process.exit(2);
}

// Not yet audited
if (!checkData.exists) {
  console.log(gateJson('UNKNOWN', pkg, null, { reason: 'not_audited' }));
  process.exit(3);
}

const score = checkData.trust_score ?? 100;
const total = checkData.total_findings ?? 0;
const summary = {
  critical: checkData.critical ?? 0,
  high: checkData.high ?? 0,
  medium: checkData.medium ?? 0,
  low: checkData.low ?? 0,
  total_findings: total,
};

// ── Decision ─────────────────────────────────────────────

if (score >= 70) {
  console.log(gateJson('PASS', pkg, score, summary));
  process.exit(0);
} else if (score >= 40) {
  console.log(gateJson('WARN', pkg, score, summary));

  // Show top findings on stderr for the agent to read
  if (total > 0) {
    try {
      const headers = {};
      if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;
      const fRes = await fetchRetry(`${API_URL}/api/findings?package=${encoded}`, { headers });
      const fData = await fRes.json();
      const findings = (fData.findings || [])
        .filter(f => f.by_design !== true && f.by_design !== 'true')
        .slice(0, 5);
      console.error(JSON.stringify(findings.map(f => ({
        severity: f.severity,
        title: f.title,
        by_design: f.by_design,
      }))));
    } catch {}
  }
  process.exit(2);
} else {
  console.log(gateJson('BLOCK', pkg, score, summary));

  if (total > 0) {
    try {
      const headers = {};
      if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;
      const fRes = await fetchRetry(`${API_URL}/api/findings?package=${encoded}`, { headers });
      const fData = await fRes.json();
      const findings = (fData.findings || [])
        .filter(f => f.by_design !== true && f.by_design !== 'true')
        .slice(0, 5);
      console.error(JSON.stringify(findings.map(f => ({
        severity: f.severity,
        title: f.title,
        by_design: f.by_design,
      }))));
    } catch {}
  }
  process.exit(1);
}

#!/usr/bin/env node
/**
 * register.mjs — Cross-platform agent registration for AgentAudit
 * Works on Windows, macOS, and Linux. No bash/jq required.
 *
 * Usage:
 *   node scripts/register.mjs <agent-name>
 *
 * Creates credentials at:
 *   - <skill-dir>/config/credentials.json (skill-local)
 *   - ~/.config/agentaudit/credentials.json (user-level backup)
 *
 * Requires: Node.js 18+ (for built-in fetch)
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const API_URL = 'https://www.agentaudit.dev';

// ── Helpers ──────────────────────────────────────────────

function writeCredentials(filePath, data) {
  const json = JSON.stringify(data, null, 2);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, json, { mode: 0o600 });
}

async function validateKeyAgainstServer(apiKey) {
  try {
    const res = await fetch(`${API_URL}/api/auth/validate`, {
      headers: { 'Authorization': `Bearer ${apiKey}` },
      signal: AbortSignal.timeout(5_000),
    });
    return res.status === 200;
  } catch {
    return false;
  }
}

// ── Args ─────────────────────────────────────────────────

const agentName = process.argv[2];
if (!agentName) {
  console.error('Usage: node scripts/register.mjs <agent-name>');
  console.error('Example: node scripts/register.mjs my-security-bot');
  process.exit(1);
}

// Validate agent name (parity with register.sh)
if (!/^[a-zA-Z0-9._-]{2,64}$/.test(agentName)) {
  console.error('Invalid agent name. Use only alphanumeric, dashes, underscores, dots (2-64 chars).');
  process.exit(1);
}

// ── Check existing key ───────────────────────────────────

const skillCredDir = path.join(__dirname, '..', 'config');
const skillCredFile = path.join(skillCredDir, 'credentials.json');
const home = process.env.HOME || process.env.USERPROFILE || '';
const xdg = process.env.XDG_CONFIG_HOME || path.join(home, '.config');
const userCredDir = path.join(xdg, 'agentaudit');
const userCredFile = path.join(userCredDir, 'credentials.json');

// Check both credential locations and validate against server
for (const checkFile of [skillCredFile, userCredFile]) {
  if (fs.existsSync(checkFile)) {
    try {
      const existing = JSON.parse(fs.readFileSync(checkFile, 'utf8'));
      if (existing.api_key) {
        const valid = await validateKeyAgainstServer(existing.api_key);
        if (valid) {
          console.log(`Already registered as "${existing.agent_name || 'unknown'}". Key validated against server.`);
          console.log(`  Key found in ${checkFile}`);
          // Ensure both locations have the key
          if (checkFile === userCredFile && !fs.existsSync(skillCredFile)) {
            writeCredentials(skillCredFile, { api_key: existing.api_key, agent_name: existing.agent_name });
            console.log(`  Restored skill-local copy to: ${skillCredFile}`);
          }
          process.exit(0);
        } else {
          console.log(`Cached key in ${checkFile} is stale (server validation failed). Re-registering...`);
          try { fs.unlinkSync(skillCredFile); } catch {}
          try { fs.unlinkSync(userCredFile); } catch {}
          break;
        }
      }
    } catch {}
  }
}

// ── Register ─────────────────────────────────────────────

console.log(`Registering agent "${agentName}" at ${API_URL}...`);

let res;
try {
  res = await fetch(`${API_URL}/api/register`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ agent_name: agentName }),
    signal: AbortSignal.timeout(15_000),
  });
} catch (err) {
  console.error(`Registration failed: ${err.message}`);
  process.exit(1);
}

if (!res.ok) {
  const text = await res.text();
  console.error(`Registration failed (HTTP ${res.status}): ${text}`);
  process.exit(1);
}

const data = await res.json();
const cred = { api_key: data.api_key, agent_name: data.agent_name };

// Save to skill-local (mode 600 — only owner can read)
writeCredentials(skillCredFile, cred);
console.log(`Saved to: ${skillCredFile}`);

// Save to user-level backup (mode 600)
try {
  writeCredentials(userCredFile, cred);
  console.log(`Backup saved to: ${userCredFile}`);
} catch (err) {
  console.log(`Could not save user-level backup: ${err.message}`);
}

console.log('');
console.log(`Registered as: ${data.agent_name}`);
console.log('You can now use gate.mjs and upload.mjs.');

#!/usr/bin/env node
/**
 * upload.mjs — Cross-platform report upload for AgentAudit
 * Works on Windows, macOS, and Linux. No bash/jq required.
 *
 * Usage:
 *   node scripts/upload.mjs <report.json>
 *   node scripts/upload.mjs -              # read from stdin
 *
 * Requires: Node.js 18+ (for built-in fetch)
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REGISTRY_URL = 'https://www.agentaudit.dev';
const MAX_PAYLOAD = 512_000;
const MAX_RETRIES = 3;

// ── Helpers ──────────────────────────────────────────────

function loadApiKey() {
  // 1. Environment variable (highest priority)
  if (process.env.AGENTAUDIT_API_KEY) return process.env.AGENTAUDIT_API_KEY;

  // 2. Skill-local credentials
  const skillCred = process.env.AGENTAUDIT_HOME
    ? path.join(process.env.AGENTAUDIT_HOME, 'config', 'credentials.json')
    : path.join(__dirname, '..', 'config', 'credentials.json');

  if (fs.existsSync(skillCred)) {
    try {
      const data = JSON.parse(fs.readFileSync(skillCred, 'utf8'));
      if (data.api_key) return data.api_key;
    } catch {}
  }

  // 3. User-level config
  const home = process.env.HOME || process.env.USERPROFILE || '';
  const xdg = process.env.XDG_CONFIG_HOME || path.join(home, '.config');
  const userCred = path.join(xdg, 'agentaudit', 'credentials.json');

  if (fs.existsSync(userCred)) {
    try {
      const data = JSON.parse(fs.readFileSync(userCred, 'utf8'));
      if (data.api_key) return data.api_key;
    } catch {}
  }

  return '';
}

async function fetchRetry(url, options, retries = MAX_RETRIES) {
  let lastError;
  let delay = 2000;
  for (let i = 0; i < retries; i++) {
    try {
      const res = await fetch(url, { ...options, signal: AbortSignal.timeout(60_000) });
      return res;
    } catch (err) {
      lastError = err;
      if (i < retries - 1) {
        await new Promise(r => setTimeout(r, delay));
        delay *= 2;
      }
    }
  }
  throw lastError;
}

function die(msg) {
  console.error(msg);
  process.exit(1);
}

// ── Read input ───────────────────────────────────────────

const input = process.argv[2];
if (!input) {
  die('Usage: node scripts/upload.mjs <report.json>\n   or: cat report.json | node scripts/upload.mjs -');
}

let rawJson;
if (input === '-') {
  // Read from stdin
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(chunk);
  rawJson = Buffer.concat(chunks).toString('utf8');
} else {
  if (!fs.existsSync(input)) die(`File not found: ${input}`);
  const stat = fs.statSync(input);
  if (stat.size > MAX_PAYLOAD) die(`Payload too large (${stat.size} bytes, max ${MAX_PAYLOAD}).`);
  rawJson = fs.readFileSync(input, 'utf8');
}

if (rawJson.length > MAX_PAYLOAD) die(`Payload too large (max ${MAX_PAYLOAD} bytes).`);

let report;
try {
  report = JSON.parse(rawJson);
} catch (e) {
  die(`Invalid JSON: ${e.message}`);
}

// ── API key ──────────────────────────────────────────────

const apiKey = loadApiKey();
if (!apiKey) {
  die('No API key found. Set AGENTAUDIT_API_KEY or run: node scripts/register.mjs <agent-name>');
}

// ── Validate required fields ─────────────────────────────

const sourceUrl = report.source_url || '';
if (!sourceUrl) {
  die([
    'VALIDATION ERROR: Missing required field "source_url"',
    '',
    'The report must include a public source URL to the package repository.',
    'Add to your report JSON:',
    '  "source_url": "https://github.com/owner/repo"',
  ].join('\n'));
}
if (!/^https?:\/\//.test(sourceUrl)) {
  die(`VALIDATION ERROR: source_url must be a valid HTTP(S) URL\n   Got: ${sourceUrl}`);
}
console.log(`source_url: ${sourceUrl}`);

const pkgName = report.skill_slug || report.package_name || '';
if (!pkgName) die('VALIDATION ERROR: Missing "skill_slug" or "package_name" field.');
console.log(`package: ${pkgName}`);

if (report.risk_score == null) die('VALIDATION ERROR: Missing "risk_score" field (integer 0-100).');
if (!report.result) die('VALIDATION ERROR: Missing "result" field (safe|caution|unsafe).');

// Auto-fix findings_count
const actualFc = Array.isArray(report.findings) ? report.findings.length : 0;
if (report.findings_count == null) {
  console.log(`Missing "findings_count" — auto-setting to ${actualFc}`);
  report.findings_count = actualFc;
} else if (report.findings_count !== actualFc) {
  console.log(`findings_count (${report.findings_count}) doesn't match findings array (${actualFc}) — correcting`);
  report.findings_count = actualFc;
}

// Ensure skill_slug is set
if (!report.skill_slug) {
  report.skill_slug = pkgName;
}

// Version tracking note
if (report.commit_sha || report.content_hash) {
  console.log('Report contains version info (commit_sha/content_hash) — passing through');
} else {
  console.log('Version info will be computed by backend enrichment');
}

// ── Upload ───────────────────────────────────────────────

console.log(`\nUploading report to ${REGISTRY_URL}/api/reports ...`);

let res;
try {
  res = await fetchRetry(`${REGISTRY_URL}/api/reports`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(report),
  });
} catch (err) {
  if (err.name === 'TimeoutError') {
    console.error('Upload timed out (60s). The server may be processing a large repository.');
    console.error('The report may still have been accepted — check the registry or retry.');
    process.exit(28);
  }
  die(`Upload failed: ${err.message}`);
}

const body = await res.text();
let data;
try { data = JSON.parse(body); } catch { data = null; }

// Handle rate limiting
if (res.status === 429) {
  console.log('Rate limited (429). Waiting 30s and retrying...');
  await new Promise(r => setTimeout(r, 30_000));
  try {
    res = await fetchRetry(`${REGISTRY_URL}/api/reports`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(report),
    });
    const body2 = await res.text();
    try { data = JSON.parse(body2); } catch { data = null; }
  } catch (err) {
    die(`Retry failed: ${err.message}`);
  }
}

if (res.status >= 200 && res.status < 300 && data) {
  const reportId = data.report_id || 'unknown';
